import { assignInlineVars } from '@vanilla-extract/dynamic';
import React, { forwardRef, useLayoutEffect, useRef, useState } from 'react';
import { useIntl } from 'react-intl';

import { loadingStateCSS } from './LoadingState.sty.js';
import { ProgressCircle } from '../../../core/components/progress/ProgressCircle.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import type { TableOptions } from '../hooks/useTable/types.js';
import type { DataTableV2Props } from '../public.api.js';
import { dataTableV2HeaderHeight } from '../variables.sty.js';

export interface DataTableV2LoadingStateProps {
  /**
   * Displays a loading indicator while the table's columns and/or data are being loaded.
   *
   * @defaultValue false
   */
  loading?: boolean;
}

/**
 * @internal
 * Extension interface to extend the tanstack table state with the loading state.
 */
export interface DataTableV2LoadingState {
  /**
   * Table state extension for loading state
   */
  loading?: boolean;
}

/**
 * Configuration hook for the DataTableV2 LoadingState feature.
 */
export function useLoadingState<T>(
  props: DataTableV2Props<T>,
  options: TableOptions<T>,
) {
  options.state = { ...options.state, loading: props.loading };
}

/**
 * Small wrapper that makes sure to only render the defined actions when the menu
 * is open.
 */
function LoadingState(props: { headerHeight: number }) {
  const { headerHeight } = props;
  const loadingContainerRef = useRef<HTMLDivElement | null>(null);
  const [height, setHeight] = useState(0);
  const intl = useIntl();

  useLayoutEffect(() => {
    if (loadingContainerRef.current) {
      setHeight(loadingContainerRef.current.clientHeight);
    }
  }, [loadingContainerRef.current?.clientHeight]);

  return (
    <Flex
      ref={loadingContainerRef}
      justifyContent="center"
      alignItems="center"
      className={loadingStateCSS}
      style={assignInlineVars({
        [dataTableV2HeaderHeight]: `${headerHeight}px`,
      })}
    >
      <ProgressCircle
        size={height > 120 ? 'large' : 'small'}
        aria-label={intl.formatMessage({
          defaultMessage: 'Loading data',
          id: 'EWfCcasdyt/QUnjk',
          description: 'Label for DataTable loading state.',
        })}
      />
    </Flex>
  );
}

/**
 * @internal
 */
export const _LoadingState = forwardRef(LoadingState);
